import React from "react";
import { BrowserRouter as Router, Routes, Route, Link } from "react-router-dom";

// --- INLINE STYLES (IITM BRANDED) ---
const styles = {
    container: {
        fontFamily: "'Poppins', sans-serif",
        minHeight: "100vh",
        backgroundColor: "#f4f7f4",
        display: "flex",
        flexDirection: "column",
        paddingBottom: "70px", // Space for bottom nav
    },
    header: {
        backgroundColor: "#427839", // IITM Green
        color: "white",
        padding: "1.2rem",
        textAlign: "center",
        boxShadow: "0 2px 8px rgba(0,0,0,0.2)",
    },
    headerTitle: {
        margin: 0,
        fontFamily: "'Bebas Neue', sans-serif",
        letterSpacing: "1.5px",
        fontSize: "24px",
    },
    content: {
        flex: 1,
        padding: "20px",
        display: "flex",
        justifyContent: "center",
    },
    card: {
        backgroundColor: "white",
        padding: "25px",
        borderRadius: "12px",
        boxShadow: "0 4px 12px rgba(0,0,0,0.08)",
        width: "100%",
        maxWidth: "500px",
        textAlign: "center",
        borderTop: "6px solid #427839",
    },
    heroImage: {
        width: "100%",
        borderRadius: "8px",
        marginBottom: "15px",
    },
    nav: {
        position: "fixed",
        bottom: 0,
        width: "100%",
        backgroundColor: "#ffffff",
        display: "flex",
        justifyContent: "space-around",
        padding: "12px 0",
        borderTop: "1px solid #eee",
        boxShadow: "0 -2px 10px rgba(0,0,0,0.05)",
    },
    link: {
        textDecoration: "none",
        color: "#666",
        fontWeight: "600",
        fontSize: "12px",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
    },
    activeLink: {
        color: "#427839",
    }
};

// --- PAGES ---
const Home = () => (
    <div style={styles.card}>
        <img
            src="https://images.unsplash.com/photo-1540575467063-178a50c2df87?auto=format&fit=crop&w=500&q=80"
            alt="Exhibition"
            style={styles.heroImage}
        />
        <h1 style={{ color: "#427839", marginBottom: '10px' }}>IITM 2026</h1>
        <p style={{ color: "#555" }}>India's Premier Travel & Tourism Exhibition. Connecting trade and consumers since 1998.</p>
        <button style={{ backgroundColor: "#427839", color: "white", border: "none", padding: "10px 20px", borderRadius: "5px", marginTop: "10px", cursor: "pointer" }}>
            View Cities
        </button>
    </div>
);

const Calendar = () => (
    <div style={styles.card}>
        <h1 style={{ color: "#427839" }}>Event Schedule</h1>
        <ul style={{ textAlign: "left", listStyle: "none", padding: 0 }}>
            <li style={{ padding: "10px 0", borderBottom: "1px solid #eee" }}>📅 <strong>Bengaluru:</strong> July 26 - 28</li>
            <li style={{ padding: "10px 0", borderBottom: "1px solid #eee" }}>📅 <strong>Chennai:</strong> August 02 - 04</li>
            <li style={{ padding: "10px 0", borderBottom: "1px solid #eee" }}>📅 <strong>Delhi:</strong> Sept 20 - 22</li>
        </ul>
    </div>
);

const Profile = () => (
    <div style={styles.card}>
        <div style={{ width: "80px", height: "80px", backgroundColor: "#eee", borderRadius: "50%", margin: "0 auto 15px", display: "flex", alignItems: "center", justifyContent: "center", fontSize: "30px" }}>👤</div>
        <h1 style={{ color: "#427839", margin: 0 }}>Exhibitor Portal</h1>
        <p style={{ color: "#777" }}>Welcome back, Partner.</p>
        <div style={{ marginTop: "20px", textAlign: "left" }}>
            <p><strong>Status:</strong> Approved</p>
            <p><strong>Stall ID:</strong> B-104</p>
        </div>
    </div>
);

const Register = () => (
    <div style={styles.card}>
        <h1 style={{ color: "#427839" }}>Visitor Registration</h1>
        <p>Register now to get your entry pass for IITM 2026.</p>
        <input type="text" placeholder="Full Name" style={{ width: "90%", padding: "10px", margin: "10px 0", borderRadius: "4px", border: "1px solid #ddd" }} />
        <input type="email" placeholder="Email Address" style={{ width: "90%", padding: "10px", margin: "10px 0", borderRadius: "4px", border: "1px solid #ddd" }} />
        <button style={{ backgroundColor: "#427839", color: "white", border: "none", padding: "12px", width: "95%", borderRadius: "5px", fontWeight: "bold", cursor: "pointer" }}>
            Submit Registration
        </button>
    </div>
);

const BottomNav = () => (
    <nav style={styles.nav}>
        <Link style={styles.link} to="/home"><span>🏠</span><span>HOME</span></Link>
        <Link style={styles.link} to="/calendar"><span>📅</span><span>EVENTS</span></Link>
        <Link style={styles.link} to="/profile"><span>👤</span><span>PORTAL</span></Link>
        <Link style={styles.link} to="/register"><span>📝</span><span>JOIN</span></Link>
    </nav>
);

// --- MAIN WEB APP ---
function WebApp() {
    return (
        <div style={styles.container}>
            <Router>
                <header style={styles.header}>
                    <h2 style={styles.headerTitle}>IITM INDIA</h2>
                </header>

                <main style={styles.content}>
                    <Routes>
                        <Route path="/home" element={<Home />} />
                        <Route path="/calendar" element={<Calendar />} />
                        <Route path="/profile" element={<Profile />} />
                        <Route path="/register" element={<Register />} />
                        <Route path="*" element={<Home />} />
                    </Routes>
                </main>

                <BottomNav />
            </Router>
        </div>
    );
}

export default WebApp;
